// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor } from "./actors.js";
import { MODULE_ID, SOCKET_NAME } from "./constants.js";
import { bridgeTrace, rollAdvantageTraceVerbose } from "./log.js";
import { bridgeRuntimeState } from "./map.js";
import { escapeHtml } from "./media.js";
import { isPrimaryActiveGm } from "./mobile-bridge.js";
// </auto-imports>
import { bridgeFlag } from "./flags.js";
// Chat roll-forwarding and full chat mirror — extracted from mobile-bridge.js.

export function shouldForwardChatRoll(message) {
  const activeGms = game.users.filter((user) => user.isGM && user.active);
  if (activeGms.length > 0) return isPrimaryActiveGm();
  const messageUserId = message.user?.id ?? message.user ?? message.userId;
  return game.user?.id === messageUserId;
}

export const ROLL_MODE_PUBLIC = "publicroll";
export const ROLL_MODE_PRIVATE = "gmroll";
export const ROLL_MODE_BLIND = "blindroll";
export const ROLL_MODE_SELF = "selfroll";

export function chatMessageAuthorId(message) {
  return message.author?.id ?? message.user ?? message.userId ?? "";
}

export function normalizeUserIdList(ids) {
  return (ids ?? []).map((id) => String(id)).filter(Boolean);
}

/**
 * Midi-QOL stores the effective mode on roll.options.rollMode; whisper/blind on the
 * document can lag behind on createChatMessage or stay empty if applyRollMode saw
 * pre-filled whisper data. Prefer roll.options, then document fields.
 */
export function resolveChatMessageRollMode(message) {
  for (const roll of message.rolls ?? []) {
    const mode = roll?.options?.rollMode;
    if (mode && mode !== "roll") return mode;
  }
  const whisper = normalizeUserIdList(message.whisper);
  if (!whisper.length) {
    return message.blind ? ROLL_MODE_BLIND : ROLL_MODE_PUBLIC;
  }
  if (message.blind === true) return ROLL_MODE_BLIND;
  const authorId = chatMessageAuthorId(message);
  if (whisper.length === 1 && whisper[0] === authorId) return ROLL_MODE_SELF;
  return ROLL_MODE_PRIVATE;
}

export function isBlindChatRollMessage(message) {
  if (message.blind === true) return true;
  return resolveChatMessageRollMode(message) === ROLL_MODE_BLIND;
}

export function midiForceHideRollEnabled() {
  return game.modules.get("midi-qol")?.active
    && game.settings.get("midi-qol", "ForceHideRoll") !== false;
}

export function midiHideRollDetailsFromPlayers() {
  if (!game.modules.get("midi-qol")?.active) return false;
  const config = game.settings.get("midi-qol", "ConfigSettings") ?? {};
  return (config.hideRollDetails ?? "none") !== "none";
}

/** Wait until roll mode metadata is present (Midi blind skills set rollMode before whisper). */
export function isChatRollForwardReady(message) {
  const rolls = message.rolls ?? [];
  if (!rolls.length) return false;
  const rollMode = resolveChatMessageRollMode(message);
  const whisper = normalizeUserIdList(message.whisper);
  if ([ROLL_MODE_BLIND, ROLL_MODE_PRIVATE, ROLL_MODE_SELF].includes(rollMode) && !whisper.length) {
    return false;
  }
  return true;
}

/**
 * Whether roll totals should reach a mobile player. Mirrors Foundry
 * ChatMessage#isContentVisible, extended with Midi-QOL rollMode + ForceHideRoll.
 */
export function isChatRollContentVisibleForUser(message, user) {
  if (!user?.id) return false;

  const rolls = message.rolls ?? [];
  if (!rolls.length) {
    const whisper = normalizeUserIdList(message.whisper);
    if (!whisper.length) return true;
    const authorId = chatMessageAuthorId(message);
    return user.id === authorId || whisper.includes(user.id);
  }

  const rollMode = resolveChatMessageRollMode(message);
  const whisper = normalizeUserIdList(message.whisper);
  const authorId = chatMessageAuthorId(message);
  const isAuthor = user.id === authorId;
  const isBlind = isBlindChatRollMessage(message);

  // Midi-QOL ForceHideRoll + blind: entire card hidden from non-GMs (chatMessageHandling.js).
  if (midiForceHideRollEnabled() && isBlind && !user.isGM) {
    return false;
  }

  // Blind: only GMs in whisper see totals (author sees "rolled privately" in Foundry).
  if (isBlind || rollMode === ROLL_MODE_BLIND) {
    return user.isGM && whisper.includes(user.id);
  }

  // Foundry isContentVisible for whispered / private rolls.
  if (whisper.length) {
    if (midiForceHideRollEnabled() && !user.isGM && !whisper.includes(user.id) && !isAuthor) {
      return false;
    }
    return whisper.includes(user.id) || isAuthor;
  }

  // Public GM rolls with Midi "Hide Roll Details" — numbers masked in client UI.
  if (!user.isGM && message.author?.isGM && midiHideRollDetailsFromPlayers()) {
    return false;
  }

  return rollMode === ROLL_MODE_PUBLIC;
}

/** Avoid duplicate socket pushes when the same message is updated after creation (e.g. flags). */
export const forwardedChatRollMessageIds = new Set();
export const pendingChatRollForwardMessageIds = new Set();
export const pendingChatRollForwardTimers = new Map();
export const chatRollForwardSkipLoggedIds = new Set();

export function markChatRollForwardPending(messageId) {
  if (!messageId || forwardedChatRollMessageIds.has(messageId)) return;
  pendingChatRollForwardMessageIds.add(messageId);
}

export function clearChatRollForwardPending(messageId) {
  if (!messageId) return;
  pendingChatRollForwardMessageIds.delete(messageId);
  chatRollForwardSkipLoggedIds.delete(messageId);
  const timer = pendingChatRollForwardTimers.get(messageId);
  if (timer) {
    window.clearTimeout(timer);
    pendingChatRollForwardTimers.delete(messageId);
  }
}

export function scheduleChatRollForwardRetry(messageId, attempt = 0) {
  if (!messageId || attempt > 8) {
    clearChatRollForwardPending(messageId);
    return;
  }
  if (pendingChatRollForwardTimers.has(messageId)) return;
  const delayMs = 300 + attempt * 250;
  const timer = window.setTimeout(() => {
    pendingChatRollForwardTimers.delete(messageId);
    if (!pendingChatRollForwardMessageIds.has(messageId)) return;
    const msg = game.messages.get(messageId);
    if (msg) forwardChatRollToMobile(msg);
    if (pendingChatRollForwardMessageIds.has(messageId)) {
      scheduleChatRollForwardRetry(messageId, attempt + 1);
    }
  }, delayMs);
  pendingChatRollForwardTimers.set(messageId, timer);
}

export function flushPendingChatRollForwards(reason) {
  if (!pendingChatRollForwardMessageIds.size) return;
  rollAdvantageTraceVerbose("flushPendingChatRollForwards", {
    reason,
    pending: [...pendingChatRollForwardMessageIds]
  });
  for (const id of [...pendingChatRollForwardMessageIds]) {
    const msg = game.messages.get(id);
    if (msg) forwardChatRollToMobile(msg);
  }
}

export function shouldForwardChatRollToMobileUser(message, user, actor) {
  if (isChatRollContentVisibleForUser(message, user)) return true;
  const mobileUse = bridgeRuntimeState().lastMobileItemUse;
  if (!mobileUse || Date.now() - mobileUse.at > 120_000) return false;
  if (user.id !== mobileUse.userId) return false;
  if (!actor.testUserPermission(user, "OWNER")) return false;
  if (resolveRollActorId(message) !== mobileUse.actorId) return false;
  const rollType = message.flags?.dnd5e?.roll?.type ?? "";
  return rollType === "attack";
}

/**
 * Actor id for routing rolls to the owning player. Attack/item cards often use token + scene with empty speaker.actor;
 * dnd5e resolves this via ChatMessage5e#getAssociatedActor — mirror that here.
 */
export function resolveRollActorId(message) {
  try {
    if (typeof message.getAssociatedActor === "function") {
      const actor = message.getAssociatedActor();
      if (actor?.id) return actor.id;
    }
  } catch (_) {
    /* non-dnd5e or partial chat implementations */
  }
  const speaker = message.speaker ?? {};
  if (speaker.actor) return String(speaker.actor);
  if (speaker.scene && speaker.token) {
    const scene = game.scenes.get(speaker.scene);
    const token = scene?.tokens.get(speaker.token);
    if (token?.actor?.id) return token.actor.id;
  }
  if (speaker.token && game.actors?.tokens) {
    const linked = game.actors.tokens[speaker.token];
    if (linked?.id) return linked.id;
  }
  return "";
}

export function stripHtml(value) {
  return String(value ?? "").replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim();
}

/** @returns {-1|0|1} disadvantage, normal, advantage — mirrors mobile roll buttons */
export function rollAdvantageModeFromRoll(roll) {
  if (!roll || typeof roll !== "object") return 0;
  const opt = roll.options ?? {};
  if (opt.disadvantage === true) return -1;
  if (opt.advantage === true) return 1;
  const compact = String(roll.formula ?? "")
    .toLowerCase()
    .replace(/\s+/g, "");
  if (compact.includes("2d20kl")) return -1;
  if (compact.includes("2d20kh")) return 1;
  return 0;
}

export function rollTypeLabel(flags) {
  const roll = flags?.dnd5e?.roll ?? {};
  const type = roll.type ?? "";
  if (type === "attack") return "Попадание";
  if (type === "save") {
    const ability = CONFIG.DND5E?.abilities?.[roll.ability]?.label ?? roll.ability ?? "";
    return `Спасбросок${ability ? ` ${game.i18n.localize(ability)}` : ""}`;
  }
  if (type === "ability") {
    const ability = CONFIG.DND5E?.abilities?.[roll.ability]?.label ?? roll.ability ?? "";
    return `Проверка${ability ? ` ${game.i18n.localize(ability)}` : ""}`;
  }
  if (type === "skill") {
    const skill = CONFIG.DND5E?.skills?.[roll.skillId]?.label ?? roll.skillId ?? "";
    return `Навык${skill ? ` ${game.i18n.localize(skill)}` : ""}`;
  }
  if (type === "tool") return "Инструмент";
  if (type === "hitDie") return "Кость хитов";
  if (type === "damage") return "Урон";
  return stripHtml(flags?.dnd5e?.roll?.type ?? "");
}

export function summarizeChatRoll(message) {
  const rolls = message.rolls ?? [];
  if (!rolls.length) return null;
  const actorId = resolveRollActorId(message);
  if (!actorId) return null;
  const actor = game.actors.get(actorId);
  const formulas = rolls.map((roll) => roll.formula).filter(Boolean);
  const totals = rolls
    .map((roll) => roll.total)
    .filter((total) => total !== undefined && total !== null)
    .map((total) => String(total));
  const first = rolls[0];
  const targetValue = Number(first?.options?.target);
  const target = Number.isFinite(targetValue) ? targetValue : null;
  const success = target == null
    ? null
    : (typeof first?.isSuccess === "boolean"
      ? first.isSuccess
      : (Number.isFinite(first?.total) ? first.total >= target : null));
  const flags = message.flags ?? {};
  const sourceFlag = bridgeFlag(message, "source");
  const label = rollTypeLabel(flags) || stripHtml(message.flavor) || "Бросок";
  let advantageMode = rollAdvantageModeFromRoll(first);
  if (advantageMode === 0 && !String(first?.formula ?? "").toLowerCase().includes("2d20")) {
    const recent = bridgeRuntimeState().lastMobileItemUse;
    if (
      recent?.advantageMode &&
      recent.actorId === actorId &&
      Date.now() - recent.at < 120_000
    ) {
      advantageMode = recent.advantageMode;
    }
  }
  return {
    messageId: message.id ?? "",
    actorId,
    actorName: message.speaker?.alias ?? actor?.name ?? "",
    source: sourceFlag === "mobile" ? "mobile" : "server",
    rollType: flags.dnd5e?.roll?.type ?? first?.options?.rollType ?? "",
    label,
    formula: formulas.join(" / "),
    total: totals.join(" / "),
    target,
    success,
    advantageMode
  };
}

export function mobileRollMessageData(user) {
  return {
    create: true,
    data: {
      flags: {
        [MODULE_ID]: {
          source: "mobile",
          userId: user.id
        }
      }
    }
  };
}

export function forwardChatRollToMobile(message) {
  if (!game.socket) {
    rollAdvantageTraceVerbose("forwardChatRoll skip", { reason: "no_socket", messageId: message?.id });
    return;
  }
  if (!shouldForwardChatRoll(message)) {
    rollAdvantageTraceVerbose("forwardChatRoll skip", { reason: "shouldForward=false", messageId: message?.id });
    return;
  }
  if (!isChatRollForwardReady(message)) {
    markChatRollForwardPending(message?.id);
    if (message?.id && !pendingChatRollForwardTimers.has(message.id)) {
      scheduleChatRollForwardRetry(message.id, 0);
    }
    if (message?.id && !chatRollForwardSkipLoggedIds.has(message.id)) {
      chatRollForwardSkipLoggedIds.add(message.id);
      rollAdvantageTraceVerbose("forwardChatRoll skip", {
        reason: "not_ready",
        messageId: message.id,
        rollsCount: message?.rolls?.length ?? 0,
        rollMode: resolveChatMessageRollMode(message),
        whisper: normalizeUserIdList(message.whisper)
      });
    }
    return;
  }
  clearChatRollForwardPending(message?.id);
  const payload = summarizeChatRoll(message);
  if (!payload?.actorId) {
    rollAdvantageTraceVerbose("forwardChatRoll skip", { reason: "no_actorId", messageId: message?.id });
    return;
  }
  if (forwardedChatRollMessageIds.has(message.id)) return;
  const actor = game.actors.get(payload.actorId);
  if (!actor) {
    rollAdvantageTraceVerbose("forwardChatRoll skip", { reason: "actor_not_found", actorId: payload.actorId });
    return;
  }
  const users = game.users.filter((user) =>
    !user.isGM &&
    actor.testUserPermission(user, "OWNER") &&
    shouldForwardChatRollToMobileUser(message, user, actor)
  );
  let emitted = 0;
  for (const user of users) {
    game.socket.emit(SOCKET_NAME, {
      event: "chat.roll",
      payload,
      meta: { targetUserId: user.id }
    });
    emitted++;
  }
  if (emitted > 0) {
    rollAdvantageTraceVerbose("forwardChatRoll emitted", {
      messageId: message.id,
      actorId: payload.actorId,
      label: payload.label,
      advantageMode: payload.advantageMode,
      formula: payload.formula,
      recipients: users.map((u) => u.name)
    });
    forwardedChatRollMessageIds.add(message.id);
    clearChatRollForwardPending(message.id);
    if (forwardedChatRollMessageIds.size > 400) {
      const stale = [...forwardedChatRollMessageIds].slice(0, 200);
      for (const id of stale) forwardedChatRollMessageIds.delete(id);
    }
  } else {
    rollAdvantageTraceVerbose("forwardChatRoll no recipients", {
      messageId: message.id,
      actorId: payload.actorId,
      rollType: message.flags?.dnd5e?.roll?.type,
      rollMode: resolveChatMessageRollMode(message),
      mobileUse: bridgeRuntimeState().lastMobileItemUse ?? null
    });
  }
}

// --- Full chat mirror (chat.card / chat.card.delete / chat.log.get) ----------
//
// The narrow `chat.roll` event above only reaches the owner of the rolling actor.
// The mirror below reproduces the browser chat log: every message the mobile user
// would see in Foundry, as a structured card.
//
// The card is composed from the MESSAGE DATA MODEL — dnd5e flags, the real Roll
// objects, and the Item/Activity documents behind them — never from how some module
// chose to render its HTML. Rendered markup is read in exactly one situation: a
// field that IS rich text and has no structured equivalent (item descriptions,
// plain chat message content). Everything structural (attack, damage, totals,
// targets, DC, crit/fumble) comes from data, so a card looks the same whether the
// message was produced by stock dnd5e, by a workflow module, or by a macro.

export const CHAT_MIRROR_HISTORY_DEFAULT = 40;
export const CHAT_MIRROR_HISTORY_MAX = 100;
/** Item descriptions run to pages; the socket payload must stay phone-sized. */
export const CHAT_MIRROR_DESCRIPTION_MAX = 1500;
export const CHAT_MIRROR_CONTENT_MAX = 2000;
export const CHAT_MIRROR_MAX_TARGETS = 12;
export const CHAT_MIRROR_MAX_PROPERTIES = 12;
export const CHAT_MIRROR_MAX_SUPPLEMENTS = 6;
export const CHAT_MIRROR_MAX_SECTIONS = 12;
/** Trailing debounce: dnd5e/workflow modules update one message several times in a burst. */
export const CHAT_MIRROR_UPDATE_DEBOUNCE_MS = 220;

// Card grouping. Stock dnd5e posts the usage card, the attack roll and the damage
// roll as three separate ChatMessages; workflow modules post a single message
// carrying all of them. Both must render as ONE card, so messages are grouped into
// a card keyed by a root message id (see chatCardRootId).
/** Window in which an unlinked roll is attached to a preceding usage card. */
export const CHAT_GROUP_FALLBACK_MS = 20_000;
/** How many neighbouring messages are examined when grouping. */
export const CHAT_GROUP_SCAN_LIMIT = 40;
export const CHAT_GROUP_MAX_PARTS = 12;

export const chatMirrorParser = new DOMParser();

/** Reads a dnd5e world setting without assuming the system is installed. */
export function dnd5eSetting(key, fallback) {
  if (game.system?.id !== "dnd5e") return fallback;
  if (!game.settings.settings.has(`dnd5e.${key}`)) return fallback;
  return game.settings.get("dnd5e", key) ?? fallback;
}

export function toStringList(values) {
  return (values ?? []).map((value) => String(value)).filter(Boolean);
}

/** Mirrors core ChatMessage#visible, evaluated for a user other than `game.user`. */
export function chatMessageVisibleForUser(message, user) {
  const whisper = normalizeUserIdList(message.whisper);
  if (!whisper.length) return true;
  if ((message.rolls ?? []).length) return true;
  return chatMessageAuthorId(message) === user.id || whisper.includes(user.id);
}

/** Mirrors core ChatMessage#isContentVisible, evaluated for a user other than `game.user`. */
export function chatMessageContentVisibleForUser(message, user) {
  const whisper = normalizeUserIdList(message.whisper);
  if (chatMessageAuthorId(message) === user.id) {
    if (message.blind && !user.isGM) return false;
  } else if (whisper.length && !whisper.includes(user.id)) {
    return false;
  }
  return chatMessageVisibleForUser(message, user);
}

/**
 * Whether a single chat message may be mirrored to a mobile (non-GM) user.
 *
 * A message is mirrored only when the user would see BOTH the message and its
 * content in the browser. Foundry itself still lists a placeholder row for rolls
 * whose content is hidden ("blind roll"); the phone drops those entirely — there is
 * no masking UI there, and a placeholder that carries the real roll object is one
 * refactor away from leaking the total.
 */
export function shouldMirrorChatMessageToUser(message, user) {
  if (!user?.id || user.isGM) return false;
  if (!chatMessageVisibleForUser(message, user)) return false;
  if (!chatMessageContentVisibleForUser(message, user)) return false;

  // Some workflow modules keep the effective mode on roll.options while
  // document.whisper is still empty, so the document-only checks above can pass
  // for a blind roll.
  const rollMode = resolveChatMessageRollMode(message);
  if (rollMode === ROLL_MODE_BLIND || isBlindChatRollMessage(message)) return false;

  const whisper = normalizeUserIdList(message.whisper);
  const isAuthor = chatMessageAuthorId(message) === user.id;
  if (
    (rollMode === ROLL_MODE_SELF || rollMode === ROLL_MODE_PRIVATE) &&
    !isAuthor &&
    !whisper.includes(user.id)
  ) {
    return false;
  }

  // "Hide Roll Details" masks GM roll numbers in the browser; the phone has no
  // masking UI, so such cards are not mirrored at all.
  if ((message.rolls ?? []).length && message.author?.isGM && midiHideRollDetailsFromPlayers()) {
    return false;
  }
  return true;
}

/**
 * HTML → readable plain text. Used only for fields that are stored as rich text
 * (item descriptions, plain message content); never to scrape a rendered card.
 */
export function chatHtmlToText(html, maxChars) {
  const raw = String(html ?? "");
  if (!raw.trim()) return "";
  const doc = chatMirrorParser.parseFromString(raw, "text/html");
  for (const el of doc.body.querySelectorAll("script, style")) el.remove();
  for (const el of doc.body.querySelectorAll("br")) el.replaceWith("\n");
  for (const el of doc.body.querySelectorAll("p, div, li, tr, h1, h2, h3, h4, h5, h6")) {
    el.append("\n");
  }
  const text = (doc.body.textContent ?? "")
    .replace(/[ \t ]+/g, " ")
    .split("\n")
    .map((line) => line.trim())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return text.length > maxChars ? `${text.slice(0, maxChars).trimEnd()}…` : text;
}

/**
 * Stored rich text still contains Foundry enricher syntax (documents are saved
 * un-enriched). The phone shows plain text, so keep the label and drop the link.
 */
export function stripFoundryEnrichers(html) {
  return String(html ?? "")
    .replace(/&(?:Reference|Lookup|Embed)\[[^\]]*\]\{([^}]*)\}/g, "$1")
    .replace(/@[A-Za-z]+\[[^\]]*\]\{([^}]*)\}/g, "$1")
    .replace(/@(?:UUID|Compendium)\[([^\]]*)\]/g, "$1")
    .replace(/\[\[[^\]]*?\]\]\{([^}]*)\}/g, "$1")
    .replace(/\[\[\/?[A-Za-z]*\s*([^\]]*?)\]\]/g, "$1");
}

// --- Grouping ---------------------------------------------------------------

export function chatSpeakerKey(message) {
  const speaker = message.speaker ?? {};
  return `${speaker.scene ?? ""}|${speaker.token ?? ""}|${speaker.actor ?? ""}|${speaker.alias ?? ""}`;
}

export function chatMessageItemUuid(message) {
  return String(message.flags?.dnd5e?.item?.uuid ?? "");
}

export function chatMessageActivityUuid(message) {
  return String(message.flags?.dnd5e?.activity?.uuid ?? "");
}

export function isChatUsageMessage(message) {
  return message.flags?.dnd5e?.messageType === "usage";
}

export function chatMessageHasRolls(message) {
  return (message.rolls ?? []).length > 0;
}

/** `from` bounds the backward scan: a card root always precedes its parts. */
export function chatMessageIndex(messageId, all, from = all.length - 1) {
  for (let i = Math.min(from, all.length - 1); i >= 0; i--) {
    if (all[i].id === messageId) return i;
  }
  return -1;
}

/**
 * Which card a message belongs to.
 *
 * 1. `flags.dnd5e.originatingMessage` — dnd5e writes this whenever a roll is
 *    launched from a card button, so it is the authoritative link when present.
 *    One extra hop is followed so a roll linked to a roll still lands on the card.
 * 2. Otherwise an unlinked roll message attaches to the MOST RECENT earlier usage
 *    card from the same speaker for the same item/activity, within
 *    CHAT_GROUP_FALLBACK_MS. "Most recent" is what makes repeated uses behave:
 *    use → roll → use → roll binds each roll to its own card. It does NOT save the
 *    pathological ordering use → use → roll → roll, where both rolls bind to the
 *    second card; there is no data left to distinguish them, so that is accepted.
 * 3. Otherwise the message is its own card.
 *
 * Membership is symmetric by construction: chatCardParts asks this same function.
 */
export function chatCardRootId(message, index, all) {
  const linked = String(message.flags?.dnd5e?.originatingMessage ?? "");
  if (linked) {
    const parent = game.messages.get(linked);
    if (parent) {
      const grandparent = String(parent.flags?.dnd5e?.originatingMessage ?? "");
      return grandparent && game.messages.get(grandparent) ? grandparent : linked;
    }
  }

  if (isChatUsageMessage(message) || !chatMessageHasRolls(message)) return message.id;
  const itemUuid = chatMessageItemUuid(message);
  if (!itemUuid) return message.id;

  const activityUuid = chatMessageActivityUuid(message);
  const speakerKey = chatSpeakerKey(message);
  const oldest = Number(message.timestamp) - CHAT_GROUP_FALLBACK_MS;
  for (let i = index - 1; i >= 0 && index - i <= CHAT_GROUP_SCAN_LIMIT; i--) {
    const candidate = all[i];
    if (Number(candidate.timestamp) < oldest) break;
    if (!isChatUsageMessage(candidate)) continue;
    if (chatSpeakerKey(candidate) !== speakerKey) continue;
    if (chatMessageItemUuid(candidate) !== itemUuid) continue;
    const candidateActivity = chatMessageActivityUuid(candidate);
    if (activityUuid && candidateActivity && candidateActivity !== activityUuid) continue;
    return candidate.id;
  }
  return message.id;
}

/** Root message plus every following message that claims it as its card root. */
export function chatCardParts(root, rootIndex, all) {
  const parts = [root];
  for (let i = rootIndex + 1; i < all.length && i - rootIndex <= CHAT_GROUP_SCAN_LIMIT; i++) {
    if (parts.length >= CHAT_GROUP_MAX_PARTS) break;
    const candidate = all[i];
    if (chatCardRootId(candidate, i, all) === root.id) parts.push(candidate);
  }
  return parts;
}

/**
 * The card a message belongs to, guaranteed to contain the message. Grouping scans
 * are deliberately bounded, so a message that claims a root the forward scan never
 * reached becomes its own card rather than vanishing from the mirror.
 */
export function resolveChatCard(message, index, all) {
  const rootId = chatCardRootId(message, index, all);
  if (rootId !== message.id) {
    const rootIndex = chatMessageIndex(rootId, all, index);
    if (rootIndex >= 0) {
      const root = all[rootIndex];
      const parts = chatCardParts(root, rootIndex, all);
      if (parts.some((part) => part.id === message.id)) return { root, parts };
    }
    return { root: message, parts: [message] };
  }
  return { root: message, parts: chatCardParts(message, index, all) };
}

// --- Card data --------------------------------------------------------------

export function localizedConfigLabel(config) {
  const label = config?.label ?? config?.name ?? "";
  return label ? game.i18n.localize(label) : "";
}

export function chatCardActor(message) {
  const actorId = resolveRollActorId(message);
  return actorId ? game.actors.get(actorId) : null;
}

/**
 * The Item behind the card, from `flags.dnd5e.item.uuid` or the item source data
 * dnd5e stores on the message when the item was consumed or deleted.
 */
export function resolveChatCardItem(message) {
  const flag = message.flags?.dnd5e?.item;
  if (!flag) return null;
  if (flag.uuid) {
    const item = fromUuidSync(flag.uuid, { strict: false });
    if (item) return item;
  }
  if (!flag.data) return null;
  const actor = chatCardActor(message);
  if (!actor) return null;
  return new Item.implementation(flag.data, { parent: actor });
}

export function resolveChatCardActivity(message, item) {
  const flag = message.flags?.dnd5e?.activity;
  if (!flag) return null;
  if (flag.uuid) {
    const activity = fromUuidSync(flag.uuid, { strict: false });
    if (activity) return activity;
  }
  return item?.system?.activities?.get?.(flag.id) ?? null;
}

/** Resolved once per card and shared across recipients — document lookups are not free. */
export function buildChatCardContext(parts) {
  const holder = parts.find((message) => message.flags?.dnd5e?.item) ?? null;
  const item = holder ? resolveChatCardItem(holder) : null;
  const activity = holder && item ? resolveChatCardActivity(holder, item) : null;
  return { holder, item, activity };
}

/**
 * Mirrors dnd5e's own card subtitle rule: spell level + school for spells, the item
 * type label otherwise.
 */
export function chatCardItemSubtitle(message, item) {
  if (item.type === "spell") {
    const level = message?.flags?.dnd5e?.use?.spellLevel ?? item.system?.level;
    const spellLevels = CONFIG.DND5E?.spellLevels ?? {};
    const spellSchools = CONFIG.DND5E?.spellSchools ?? {};
    const levelLabel = spellLevels[level] ? game.i18n.localize(spellLevels[level]) : "";
    const schoolLabel = localizedConfigLabel(spellSchools[item.system?.school]);
    return [levelLabel, schoolLabel].filter(Boolean).join(" • ");
  }
  if (item.system?.type?.label) return String(item.system.type.label);
  const typeKey = CONFIG.Item?.typeLabels?.[item.type];
  return typeKey ? game.i18n.localize(typeKey) : "";
}

/**
 * The bridge runs in a GM tab, so the GM's identification state must never decide
 * what a player sees: an unidentified item exposes only its unidentified name and
 * description, exactly as it would in that player's browser.
 */
export function chatCardItemPayload(context) {
  const { holder, item } = context;
  if (!item) return null;
  const identified = item.system?.identified !== false;
  const description = identified
    ? (item.system?.description?.chat || item.system?.description?.value || "")
    : (item.system?.unidentified?.description || "");
  const name = identified
    ? (item.name ?? "")
    : (item.system?.unidentified?.name || item.name || "");
  return {
    name: String(name),
    subtitle: chatCardItemSubtitle(holder, item),
    img: String(item.img ?? ""),
    description: chatHtmlToText(stripFoundryEnrichers(description), CHAT_MIRROR_DESCRIPTION_MAX)
  };
}

/** Component tags, card properties and activation labels — all prepared item data. */
export function chatCardProperties(context) {
  const { item, activity } = context;
  if (!item || item.system?.identified === false) return [];
  const values = [
    ...(item.labels?.components?.tags ?? []),
    ...(item.system?.cardProperties ?? []),
    ...Object.values(activity?.activationLabels ?? {})
  ];
  const seen = new Set();
  for (const value of values) {
    const text = stripHtml(value);
    if (text) seen.add(text);
  }
  return [...seen].slice(0, CHAT_MIRROR_MAX_PROPERTIES);
}

export function chatCardSupplements(context) {
  const { item, activity } = context;
  const out = [];
  const condition = activity?.activation?.condition;
  if (condition) {
    out.push(`${game.i18n.localize("DND5E.Trigger")}: ${stripHtml(condition)}`);
  }
  const materials = item?.system?.materials?.value;
  if (materials && item.system?.identified !== false) {
    out.push(`${game.i18n.localize("DND5E.Materials")}: ${stripHtml(materials)}`);
  }
  return out.slice(0, CHAT_MIRROR_MAX_SUPPLEMENTS);
}

/**
 * Narrative text of the card: `content` of the parts that are not rendered item
 * cards. An item card is skipped because the structured item block replaces it, and
 * a roll's `content` is skipped when it is just the total core wrote there — but a
 * module that posts real prose alongside a roll keeps its prose.
 */
export function chatCardText(parts, context) {
  const chunks = [];
  for (const message of parts) {
    if (message.flags?.dnd5e?.item && context.item) continue;
    const text = chatHtmlToText(stripFoundryEnrichers(message.content), CHAT_MIRROR_CONTENT_MAX);
    if (!text) continue;
    const totals = new Set((message.rolls ?? []).map((roll) => String(roll.total)));
    if (totals.has(text)) continue;
    chunks.push(text);
  }
  return chunks.join("\n\n").slice(0, CHAT_MIRROR_CONTENT_MAX);
}

// --- Rolls ------------------------------------------------------------------

export function chatRollIsD20(roll) {
  const die = (roll?.dice ?? [])[0];
  return !!die && Number(die.faces) === 20;
}

/**
 * Critical / fumble only exist on dnd5e's D20Roll, and its `d20` getter assumes a
 * d20 first term — gate on the die the same way dnd5e's own chat renderer does.
 */
export function chatD20Outcome(roll) {
  if (!chatRollIsD20(roll)) return { critical: false, fumble: false };
  return { critical: roll.isCritical === true, fumble: roll.isFumble === true };
}

export function chatRollDamageTypeIds(roll) {
  const ids = new Set();
  if (roll?.options?.type) ids.add(String(roll.options.type));
  for (const type of roll?.options?.types ?? []) ids.add(String(type));
  return [...ids];
}

export function chatRollIsHealing(roll) {
  const ids = chatRollDamageTypeIds(roll);
  const healing = CONFIG.DND5E?.healingTypes ?? {};
  return ids.length > 0 && ids.every((id) => id in healing);
}

/** Damage / healing type names, localized by Foundry. */
export function chatDamageTypeLabels(roll) {
  return chatRollDamageTypeIds(roll)
    .map((id) => {
      const config = CONFIG.DND5E?.damageTypes?.[id] ?? CONFIG.DND5E?.healingTypes?.[id];
      return localizedConfigLabel(config) || id;
    })
    .filter(Boolean);
}

/**
 * Roll classification straight from the data model.
 *
 * `flags.dnd5e.roll.type` covers stock dnd5e, where one message carries one kind of
 * roll. When a message carries a whole workflow (several rolls, no per-message roll
 * type), each Roll is classified by its own class plus the activity type recorded in
 * `flags.dnd5e.activity.type` — no module markup and no module flags involved.
 *
 * @param {number} d20Ordinal  Which d20 roll this is within the message: the
 *   activity's own d20 comes first, any later d20 in the same message is a target save.
 */
export function chatRollKind(message, roll, d20Ordinal) {
  const flagged = String(message.flags?.dnd5e?.roll?.type ?? "");
  if (flagged) return flagged;

  const DamageRoll = CONFIG.Dice?.DamageRoll;
  if (DamageRoll && roll instanceof DamageRoll) {
    return chatRollIsHealing(roll) ? "healing" : "damage";
  }

  const D20Roll = CONFIG.Dice?.D20Roll;
  if (D20Roll && roll instanceof D20Roll) {
    if (d20Ordinal > 0) return "save";
    switch (String(message.flags?.dnd5e?.activity?.type ?? "")) {
      case "attack": return "attack";
      case "save": return "save";
      case "check": return "check";
      default: return "check";
    }
  }
  return "";
}

/** One entry per DiceTerm — the same breakdown Foundry shows in the dice tooltip. */
export function chatRollParts(roll) {
  return (roll?.dice ?? []).map((die) => ({
    formula: String(die.expression ?? ""),
    total: die.total == null ? "" : String(die.total),
    flavor: String(die.flavor ?? ""),
    dice: (die.results ?? []).map((result) => {
      const value = Number(result.result) || 0;
      const faces = Number(die.faces) || 0;
      const marked = result.success !== undefined || result.failure !== undefined;
      return {
        result: value,
        faces,
        discarded: result.active === false || result.discarded === true,
        rerolled: result.rerolled === true,
        exploded: result.exploded === true,
        success: result.success === true,
        failure: result.failure === true,
        min: !marked && value === 1,
        max: !marked && faces > 0 && value === faces
      };
    })
  }));
}

/** Ability / skill name behind a typed roll, so "Save" reads as "Save · Dexterity". */
export function chatRollDetailLabel(message, roll) {
  const flag = message.flags?.dnd5e?.roll ?? {};
  if (flag.ability) {
    const label = localizedConfigLabel(CONFIG.DND5E?.abilities?.[flag.ability]);
    if (label) return label;
  }
  if (flag.skillId) {
    const label = localizedConfigLabel(CONFIG.DND5E?.skills?.[flag.skillId]);
    if (label) return label;
  }
  return stripHtml(roll?.options?.flavor ?? "");
}

/**
 * dnd5e `challengeVisibility` decides whether players see the DC / target number.
 * GMs and the roll's own author always do.
 */
export function chatChallengeVisibleForUser(message, user) {
  if (user.isGM || chatMessageAuthorId(message) === user.id) return true;
  switch (dnd5eSetting("challengeVisibility", "player")) {
    case "all": return true;
    case "player": return !(message.author?.isGM);
    default: return false;
  }
}

/** dnd5e `attackRollVisibility`: "all" | "hideAC" | "none" (default hides the tray). */
export function chatAttackVisibilityForUser(user) {
  return user.isGM ? "all" : dnd5eSetting("attackRollVisibility", "none");
}

/**
 * OPTIONAL enrichment. Modules that resolve a whole attack workflow already know
 * whether it was a critical; reading that costs one flag lookup. Absent flags change
 * nothing — the D20Roll itself is still the primary source above.
 * Currently understood: midi-qol (`isCritical` / `isFumble`).
 */
export function moduleAttackOutcome(message) {
  const midi = message.flags?.["midi-qol"];
  if (!midi) return { critical: false, fumble: false };
  return { critical: midi.isCritical === true, fumble: midi.isFumble === true };
}

/** `parts` must already be filtered by shouldMirrorChatMessageToUser — no gate here. */
export function chatCardSections(parts, user) {
  const sections = [];
  for (const message of parts) {
    const challengeVisible = chatChallengeVisibleForUser(message, user);
    const moduleOutcome = moduleAttackOutcome(message);
    let d20Ordinal = 0;
    for (const roll of message.rolls ?? []) {
      if (sections.length >= CHAT_MIRROR_MAX_SECTIONS) return sections;
      const isD20 = chatRollIsD20(roll);
      const kind = chatRollKind(message, roll, isD20 ? d20Ordinal : 0);
      if (isD20) d20Ordinal++;

      const outcome = chatD20Outcome(roll);
      const targetValue = Number(roll?.options?.target);
      const target = challengeVisible && Number.isFinite(targetValue) ? targetValue : null;
      const success = target == null
        ? null
        : (typeof roll.isSuccess === "boolean" ? roll.isSuccess : Number(roll.total) >= target);
      sections.push({
        kind,
        label: chatRollDetailLabel(message, roll),
        formula: String(roll.formula ?? ""),
        total: roll.total == null ? "" : String(roll.total),
        critical: outcome.critical
          || roll?.options?.isCritical === true
          || (kind === "attack" && moduleOutcome.critical),
        fumble: outcome.fumble || (kind === "attack" && moduleOutcome.fumble),
        advantageMode: rollAdvantageModeFromRoll(roll),
        target,
        success,
        damageTypes: chatDamageTypeLabels(roll),
        parts: chatRollParts(roll)
      });
    }
  }
  return sections;
}

// --- Targets ----------------------------------------------------------------

/**
 * OPTIONAL enrichment. Modules that resolve hits themselves record the outcome per
 * target uuid; using it beats re-deriving hit/miss from the roll. With no such flags
 * the map is empty and the attack-roll-vs-recorded-AC path below still fills the rows.
 * Currently understood: midi-qol (`targetUuids` / `hitTargetUuids` / `hitECTargetUuids`).
 */
export function moduleTargetOutcomes(parts) {
  const outcomes = new Map();
  for (const message of parts) {
    const midi = message.flags?.["midi-qol"];
    if (!midi) continue;
    const all = toStringList(midi.targetUuids);
    const hits = new Set([
      ...toStringList(midi.hitTargetUuids),
      ...toStringList(midi.hitECTargetUuids)
    ]);
    if (!all.length && !hits.size) continue;
    for (const uuid of all) outcomes.set(uuid, hits.has(uuid));
    for (const uuid of hits) outcomes.set(uuid, true);
  }
  return outcomes;
}

/** Fallback row for a target uuid that no message recorded name/img/ac for. */
export function chatTargetRowFromUuid(uuid) {
  const doc = fromUuidSync(uuid, { strict: false });
  if (!doc) return null;
  const actor = doc.actor ?? doc;
  const acValue = Number(actor?.system?.attributes?.ac?.value);
  return {
    name: String(doc.name ?? actor?.name ?? ""),
    img: String(doc.texture?.src ?? actor?.img ?? ""),
    ac: Number.isFinite(acValue) ? acValue : null,
    hit: null
  };
}

/**
 * Targets come from `flags.dnd5e.targets`, which records name / img / AC at roll
 * time. Hit/miss is derived from this card's attack section against that AC, unless
 * a module already resolved it (see moduleTargetOutcomes).
 */
export function chatCardTargets(parts, sections, user) {
  const visibility = chatAttackVisibilityForUser(user);
  if (visibility === "none") return [];

  const rows = new Map();
  for (const message of parts) {
    for (const target of message.flags?.dnd5e?.targets ?? []) {
      const uuid = String(target.uuid ?? target.name ?? "");
      if (!uuid || rows.has(uuid)) continue;
      const acValue = Number(target.ac);
      rows.set(uuid, {
        name: String(target.name ?? ""),
        img: String(target.img ?? ""),
        ac: Number.isFinite(acValue) ? acValue : null,
        hit: null
      });
    }
  }

  for (const [uuid, hit] of moduleTargetOutcomes(parts)) {
    const row = rows.get(uuid) ?? chatTargetRowFromUuid(uuid);
    if (!row) continue;
    row.hit = hit;
    rows.set(uuid, row);
  }

  const attack = sections.find((section) => section.kind === "attack");
  if (attack && attack.total !== "") {
    for (const row of rows.values()) {
      if (row.hit != null || row.ac == null) continue;
      row.hit = attack.critical || (!attack.fumble && Number(attack.total) >= row.ac);
    }
  }

  return [...rows.values()].slice(0, CHAT_MIRROR_MAX_TARGETS).map((row) => ({
    name: row.name,
    img: row.img,
    ac: visibility === "all" ? row.ac : null,
    hit: row.hit
  }));
}

// --- Payload ----------------------------------------------------------------

/** Token art beats actor art — the phone should show what stands on the map. */
export function chatSpeakerImage(message, actor) {
  const speaker = message.speaker ?? {};
  if (speaker.scene && speaker.token) {
    const token = game.scenes.get(speaker.scene)?.tokens.get(speaker.token);
    const src = token?.texture?.src;
    if (src) return String(src);
  }
  return String(actor?.img ?? "");
}

/**
 * Builds one card for one recipient. Parts the user may not see are dropped
 * individually, so a public usage card keeps its item block even when a linked
 * damage roll was made privately. A card with no visible part is not sent at all.
 */
export function buildChatCardPayload(cardId, parts, context, user) {
  const visible = parts.filter((message) => shouldMirrorChatMessageToUser(message, user));
  if (!visible.length) return null;

  const head = visible[0];
  const actor = chatCardActor(head);
  const sections = chatCardSections(visible, user);
  return {
    messageId: cardId,
    timestamp: Number(head.timestamp) || Date.now(),
    authorName: head.author?.name ?? "",
    speakerName: head.speaker?.alias ?? actor?.name ?? head.author?.name ?? "",
    speakerImg: chatSpeakerImage(head, actor),
    actorId: actor?.id ?? "",
    ownedByUser: !!actor && actor.testUserPermission(user, "OWNER"),
    whispered: visible.some((message) => normalizeUserIdList(message.whisper).length > 0),
    rollMode: resolveChatMessageRollMode(head),
    source: visible.some((message) => bridgeFlag(message, "source") === "mobile")
      ? "mobile"
      : "server",
    flavor: stripHtml(head.flavor ?? ""),
    text: chatCardText(visible, context),
    item: chatCardItemPayload(context),
    properties: chatCardProperties(context),
    supplements: chatCardSupplements(context),
    sections,
    targets: chatCardTargets(visible, sections, user)
  };
}

// --- Emission ---------------------------------------------------------------

export const chatMirrorPendingIds = new Set();
export const chatMirrorRetryTimers = new Map();
export const chatMirrorDebounceTimers = new Map();

/** Roll metadata can land after createChatMessage; emitting early could leak a blind roll. */
export function isChatMirrorReady(message) {
  if (!(message.rolls ?? []).length) return true;
  return isChatRollForwardReady(message);
}

export function clearChatMirrorPending(messageId) {
  if (!messageId) return;
  chatMirrorPendingIds.delete(messageId);
  const timer = chatMirrorRetryTimers.get(messageId);
  if (timer) {
    window.clearTimeout(timer);
    chatMirrorRetryTimers.delete(messageId);
  }
}

export function scheduleChatMirrorRetry(messageId, attempt = 0) {
  if (!messageId || attempt > 8) {
    clearChatMirrorPending(messageId);
    return;
  }
  if (chatMirrorRetryTimers.has(messageId)) return;
  const timer = window.setTimeout(() => {
    chatMirrorRetryTimers.delete(messageId);
    if (!chatMirrorPendingIds.has(messageId)) return;
    const msg = game.messages.get(messageId);
    if (!msg) {
      clearChatMirrorPending(messageId);
      return;
    }
    forwardChatCardToMobile(msg);
    if (chatMirrorPendingIds.has(messageId)) scheduleChatMirrorRetry(messageId, attempt + 1);
  }, 300 + attempt * 250);
  chatMirrorRetryTimers.set(messageId, timer);
}

/** Coalesce the burst of updateChatMessage hooks a workflow fires on one message. */
export function queueChatCardUpdate(message) {
  const messageId = message?.id;
  if (!messageId) return;
  if (chatMirrorDebounceTimers.has(messageId)) return;
  const timer = window.setTimeout(() => {
    chatMirrorDebounceTimers.delete(messageId);
    const msg = game.messages.get(messageId);
    if (msg) forwardChatCardToMobile(msg);
  }, CHAT_MIRROR_UPDATE_DEBOUNCE_MS);
  chatMirrorDebounceTimers.set(messageId, timer);
}

/** Emits the whole card the message belongs to, not the message on its own. */
export function emitChatCardForMessage(message) {
  const all = game.messages?.contents ?? [];
  const index = chatMessageIndex(message.id, all);
  if (index < 0) return;

  const { root, parts } = resolveChatCard(message, index, all);
  const context = buildChatCardContext(parts);
  const recipients = [];
  for (const user of game.users) {
    if (user.isGM) continue;
    const payload = buildChatCardPayload(root.id, parts, context, user);
    if (!payload) continue;
    game.socket.emit(SOCKET_NAME, {
      event: "chat.card",
      payload,
      meta: { targetUserId: user.id }
    });
    recipients.push(user.name);
  }
  if (recipients.length) {
    bridgeTrace("chat.card", { cardId: root.id, parts: parts.length, recipients });
  }
}

export function forwardChatCardToMobile(message) {
  if (!game.socket || !message?.id) return;
  // Same single-emitter rule as chat.roll: primary GM, or the author's own tab
  // when no GM session is open.
  if (!shouldForwardChatRoll(message)) return;
  if (!isChatMirrorReady(message)) {
    chatMirrorPendingIds.add(message.id);
    scheduleChatMirrorRetry(message.id, 0);
    return;
  }
  clearChatMirrorPending(message.id);
  emitChatCardForMessage(message);
}

/**
 * Only the message id travels, so deletions need no visibility filtering. A deleted
 * roll may have been one section of a grouped card, so the card is re-sent without
 * it — but only the explicit `originatingMessage` link survives deletion, since the
 * document is already out of `game.messages`. A card grouped by the time-window
 * fallback keeps its stale section until the next `chat.log.get`.
 */
export function forwardChatCardDeletionToMobile(message) {
  if (!game.socket || !message?.id) return;
  if (!shouldForwardChatRoll(message)) return;
  clearChatMirrorPending(message.id);
  for (const user of game.users) {
    if (user.isGM) continue;
    game.socket.emit(SOCKET_NAME, {
      event: "chat.card.delete",
      payload: { messageId: message.id },
      meta: { targetUserId: user.id }
    });
  }
  const linked = String(message.flags?.dnd5e?.originatingMessage ?? "");
  const root = linked ? game.messages.get(linked) : null;
  if (root) emitChatCardForMessage(root);
}

/** `chat.log.get` — newest `limit` visible cards, oldest first (app appends at the bottom). */
export function listChatLogForUser(user, payload) {
  const requested = Number(payload?.limit);
  const limit = Math.min(
    Math.max(Number.isFinite(requested) ? Math.trunc(requested) : CHAT_MIRROR_HISTORY_DEFAULT, 1),
    CHAT_MIRROR_HISTORY_MAX
  );
  const all = game.messages?.contents ?? [];
  const seen = new Set();
  const cards = [];
  for (let i = all.length - 1; i >= 0 && cards.length < limit; i--) {
    const { root, parts } = resolveChatCard(all[i], i, all);
    if (seen.has(root.id)) continue;
    seen.add(root.id);
    const card = buildChatCardPayload(root.id, parts, buildChatCardContext(parts), user);
    if (card) cards.push(card);
  }
  cards.sort((a, b) => a.timestamp - b.timestamp);
  return { messages: cards, hasMore: cards.length >= limit };
}

/** Maps a leading "/command" token (case-insensitive) to a Foundry chat roll mode. */
export const CHAT_ROLL_COMMAND_MODES = {
  roll: ROLL_MODE_PUBLIC,
  r: ROLL_MODE_PUBLIC,
  publicroll: ROLL_MODE_PUBLIC,
  pr: ROLL_MODE_PUBLIC,
  gmroll: ROLL_MODE_PRIVATE,
  gr: ROLL_MODE_PRIVATE,
  blindroll: ROLL_MODE_BLIND,
  br: ROLL_MODE_BLIND,
  selfroll: ROLL_MODE_SELF,
  sr: ROLL_MODE_SELF
};

/**
 * Recognizes a leading Foundry roll command ("/r 1d20", "/gmroll 1d20 # Stealth")
 * typed into the phone chat input. Returns null for plain text or any other
 * "/command" (e.g. "/w", "/ic") so the caller falls through to the existing plain
 * OOC message path unchanged — only the roll family below is implemented.
 */
export function parseChatRollCommand(content) {
  const match = /^\/(\S+)\s*([\s\S]*)$/.exec(content);
  if (!match) return null;
  const rollMode = CHAT_ROLL_COMMAND_MODES[match[1].toLowerCase()];
  if (!rollMode) return null;
  const rest = match[2] ?? "";
  const hashIndex = rest.indexOf("#");
  const formula = (hashIndex === -1 ? rest : rest.slice(0, hashIndex)).trim();
  const flavor = hashIndex === -1 ? "" : rest.slice(hashIndex + 1).trim();
  return { rollMode, formula, flavor };
}

/**
 * Leading "/roll" family command — builds and evaluates a Foundry Roll and posts it
 * authored by the requesting player, never by the GM tab that actually runs this
 * code. rollData is resolved from the player's selected actor (payload.actorId)
 * when given, so formulas like "1d20 + @abilities.str.mod" work.
 *
 * Attribution: Roll#toMessage builds message data defaulting `author` to whoever
 * is running this code (the GM tab's game.user), same as any other document
 * created from here — so the data is built with {create:false} and `author` is
 * overwritten to the player's id before the document actually gets created, rather
 * than trusting toMessage's own author handling to survive evaluate()/toMessage()
 * (unverified against live Foundry v13.348 — flagged in the delivery report).
 */
export async function sendChatRollMessage(user, payload, rollCommand) {
  const { rollMode, formula, flavor } = rollCommand;
  if (!formula) return { sent: false, error: "empty_formula" };
  try {
    let rollData = {};
    if (payload?.actorId) {
      const actor = getOwnedActor(user, payload.actorId);
      rollData = actor?.getRollData?.() ?? {};
    }
    const roll = Roll.create ? Roll.create(formula, rollData) : new Roll(formula, rollData);
    await roll.evaluate();
    const messageData = await roll.toMessage(
      { speaker: { alias: user.name }, flavor: flavor || undefined },
      { rollMode, create: false }
    );
    messageData.author = user.id;
    const msg = await ChatMessage.create(messageData, { rollMode });
    return { sent: true, messageId: msg?.id ?? null, rolled: true };
  } catch (err) {
    return { sent: false, error: "bad_formula", detail: String(err?.message ?? err) };
  }
}

/**
 * `chat.message.send` — post an OOC message authored by the requesting mobile
 * player (sender substitution), never by the GM tab that actually runs this
 * code. A leading Foundry roll command ("/roll", "/gmroll", …) is rolled instead
 * of posted as text — see sendChatRollMessage. Anything else (plain text, or any
 * other "/command") stays a plain OOC message; no IC/actor speaker.
 */
export async function sendChatMessage(user, payload) {
  const content = String(payload?.content ?? "").trim();
  if (!content) return { sent: false, error: "empty" };

  const rollCommand = parseChatRollCommand(content);
  if (rollCommand) return sendChatRollMessage(user, payload, rollCommand);

  const trimmed = content.length > CHAT_MIRROR_CONTENT_MAX
    ? content.slice(0, CHAT_MIRROR_CONTENT_MAX)
    : content;
  try {
    const data = {
      author: user.id, // v12+/v13 field (was `user`)
      content: `<p>${escapeHtml(trimmed)}</p>`,
      speaker: { alias: user.name },
      style: CONST.CHAT_MESSAGE_STYLES?.OOC ?? CONST.CHAT_MESSAGE_TYPES?.OOC ?? 1
    };
    if (payload?.rollMode) ChatMessage.applyRollMode?.(data, payload.rollMode);
    const msg = await ChatMessage.create(data);
    return { sent: true, messageId: msg?.id ?? null };
  } catch (err) {
    return { sent: false, error: String(err?.message ?? err) };
  }
}

/** DM chat command `push X` → unsolicited push to all non-GM connected users. */
export function forwardPushTestToMobile(message) {
  if (!game.socket) return;
  const authorId = chatMessageAuthorId(message);
  const author = game.users.get(authorId);
  if (!author?.isGM) return;
  const text = String(message?.content ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const match = /^push\s+(\S+)/i.exec(text);
  if (!match) return;
  const secret = match[1];
  const users = game.users.filter((user) => !user.isGM);
  for (const user of users) {
    game.socket.emit(SOCKET_NAME, {
      event: "push.test",
      payload: { secret },
      meta: { targetUserId: user.id }
    });
  }
}

export const sceneInvalidatePending = new Map();

/**
 * Push a `scene.invalidate` event to mobile players so they re-fetch JSON state
 * (kind="dynamic") or the cached background (kind="background"). Only the primary
 * active GM emits, to avoid duplicate events from multiple desktop clients.
 *
 * Bursts are throttled to one push per window, but the window must never eat the
 * *last* event of a burst. A token walking a route writes its intermediate
 * positions to the document, so a single move arrives as a stream of updates
 * whose final member — the one carrying where the token actually ended up — is
 * the likeliest of all to land inside the window. Dropping it leaves every phone
 * holding a snapshot from the middle of the walk, with nothing further coming to
 * correct it.
 */
